$("#m-search").addEventListener("keydown", e => { if (e.key === "Enter") $("#m-search-run").click(); });
$("#m-search-run").onclick = async () => { const q = $("#m-search").value.trim() || "jev"; $("#m-search-out").innerHTML = "検索中…"; try { const r = await apiFetch("hf", `https://huggingface.co/api/models?search=${encodeURIComponent(q)}&sort=lastModified&direction=-1&limit=40`);
  $("#m-search-out").innerHTML = "<table><tr><th>モデル</th><th>更新</th><th>DL</th><th>❤</th><th>タグ</th><th>ブラウザ</th><th></th></tr>" + r.map(m => { const tags = m.tags || []; const web = tags.includes("transformers.js") || tags.includes("onnx"); const lic = tags.find(t => t.startsWith("license:"))?.slice(8) || ""; const lang = tags.filter(t => ["ja", "en", "multilingual"].includes(t)).join("/"); return `<tr><td><a href="https://huggingface.co/${m.id}" target="_blank" rel="noopener">${esc(m.id)}</a></td><td class="small">${(m.lastModified || "").slice(0, 10)}</td><td>${m.downloads ?? ""}</td><td>${m.likes ?? ""}</td><td class="small">${lic} ${lang} ${tags.includes("gguf") ? "gguf" : ""} ${tags.includes("safetensors") ? "safetensors" : ""}</td><td>${web ? "✅ onnx" : "PC 用"}</td><td>${web ? `<button class="small m-fill" data-id="${m.id}">JSON に入れる</button>` : ""}</td></tr>`; }).join("") + "</table><p class='muted small'>「ブラウザ」列が ✅ でも入力形式（open-jev 形か、cross-encoder か、Laya 形か、独自か）はモデルカードで確認が必要。open-jev 形なら kind: open-jev-onnx で動く。</p>";
  $$(".m-fill").forEach(b => b.onclick = () => { $("#m-json").value = JSON.stringify({ name: b.dataset.id.split("/").pop().replace(/[^a-z0-9]+/gi, "_").toLowerCase(), kind: "open-jev-onnx", hf_id: b.dataset.id, dtype: "q4", dtype_webgpu: "q4f16", language: "en", note: "入力形式を要確認" }, null, 1); }); } catch (e) { $("#m-search-out").textContent = "検索失敗: " + e.message; } };
