export async function refreshSettings() { const ks = await store.keys(); const by = {}; for (const k of ks) { if (!k.includes("/")) continue; const [m] = k.split("/"); by[m] = (by[m] || 0) + ((await store.get(k))?.byteLength || 0); } $("#s-models").innerHTML = Object.keys(by).length ? "<table><tr><th>モデル</th><th>サイズ</th><th></th></tr>" + Object.entries(by).map(([m, b]) => `<tr><td>${esc(m)}</td><td>${(b / 1e6).toFixed(1)} MB</td><td><button data-m="${m}" class="s-del">削除</button></td></tr>`).join("") + "</table>" : "保存されたモデルはありません（open-jev-onnx はブラウザのキャッシュに入ります）"; $$(".s-del").forEach(b => b.onclick = async () => { for (const k of await store.keys()) if (k.startsWith(b.dataset.m + "/")) await store.del(k); refreshSettings(); markStored(); storageInfo(); });
  const qs = quotaStatus(); const cnt = await store.cacheCount().catch(() => 0); $("#s-quota").innerHTML = `<p class="hint">すべて無料の公開 API。各 API の無料枠より少なめの上限を端末内で数え、超えたら呼ばずにスキップする。同じ URL の応答はキャッシュ（右列の TTL）し、キャッシュ命中は枠を消費しない。現在のキャッシュ ${cnt} 件。</p><div class="tw"><table><tr><th>API</th><th>今日</th><th>1 時間</th><th>1 分</th><th>文字/日</th><th>間隔</th><th>キャッシュ</th><th>命中</th><th>無料枠</th></tr>${qs.map(x => { const warn = (u, l) => l && u >= l * 0.8 ? "warn" : ""; return `<tr><td>${x.api}</td><td class="${warn(x.used_day, x.limit_day)}">${x.used_day}${x.limit_day ? " / " + x.limit_day : ""}</td><td class="${warn(x.used_hour, x.limit_hour)}">${x.limit_hour ? x.used_hour + " / " + x.limit_hour : ""}</td><td>${x.limit_min ? x.used_min + " / " + x.limit_min : ""}</td><td class="${warn(x.chars, x.limit_chars)}">${x.limit_chars ? x.chars + " / " + x.limit_chars : ""}</td><td>${x.interval ? (x.interval / 1000).toFixed(1) + " s" : ""}</td><td>${x.ttl ? (x.ttl >= 86400 ? (x.ttl / 86400) + " 日" : x.ttl >= 3600 ? (x.ttl / 3600) + " 時間" : (x.ttl / 60) + " 分") : "なし"}</td><td>${x.cache_hits}</td><td class="small muted">${esc(x.note)}</td></tr>`; }).join("")}</table></div>`;
  $("#s-env").innerHTML = `<span>UA</span><span class="small">${navigator.userAgent}</span><span>WebGPU</span><span>${navigator.gpu ? "あり" : "なし（WASM）"}</span><span>CPU</span><span>${navigator.hardwareConcurrency ?? "?"} コア</span><span>メモリ</span><span>${navigator.deviceMemory ? navigator.deviceMemory + " GB" : "?"}</span><span>Service Worker</span><span>${navigator.serviceWorker?.controller ? "制御中" : "未"}</span><span>オンライン</span><span>${navigator.onLine ? "はい" : "いいえ"}</span><span>アプリ</span><span>${VERSION}</span>`; storageInfo(); }
$("#s-cache-clear").onclick = async () => { await cacheClear(); refreshSettings(); status("キャッシュを消しました（次回の取得は無料枠を消費します）"); }; $("#s-quota-reset").onclick = () => { if (confirm("使用回数の記録をリセットしますか？（実際の無料枠はリセットされません。日付が変わると自動で戻ります）")) { quotaReset(); refreshSettings(); } };

