$("#sheet-file").onchange = async e => { const f = e.target.files[0]; if (f) sheetPreview(parseCsv(await f.text()), f.name); };
$("#wh-save").onclick = () => { conf.set("discord", $("#wh-discord").value.trim()); conf.set("slack", $("#wh-slack").value.trim()); status("保存しました"); };
$("#wh-test").onclick = async () => { const c = conf.load(); const t = `JEV Lab テスト送信 ${new Date().toLocaleString()}`; const out = []; try { if (c.discord) { await sendDiscord(c.discord, t); out.push("Discord OK"); } if (c.slack) { await sendSlack(c.slack, t); out.push("Slack 送信（no-cors のため結果は確認できません）"); } } catch (e) { out.push("失敗: " + e.message); } $("#wh-out").textContent = out.join(" / ") || "Webhook URL を入れて保存してください"; };
/* 監視（定点観測） */
let watchTimer = null, watchSeen = new Set();
async function watchTick() { const src = $("#watch-src").value; const before = new Set(oItems.filter(i => !i.error).map(i => i.url)); try { if (src === "queries") { const qs = savedQueries(); if (!qs.length) return $("#watch-out").textContent = "履歴がありません"; $("#o-q").value = qs[0]; await doCollect(qs[0], { silentHistory: true }); } else if (src === "bsky-home") await importItems(await bluesky.timeline(40), "Bluesky ホーム"); else if (src === "bsky-notif") await importItems(await bluesky.notifications(40), "Bluesky 通知"); else if (src === "masto-home") await importItems(await mastodon.home(40), "Mastodon ホーム"); else if (src === "sheet") { const rows = await sheetCsv($("#sheet-url").value); const texts = rows.slice(1).map(r => r.join(" / ")).filter(Boolean); await importItems(texts.map((t, i) => ({ source: "sheet", title: `行 ${i + 2}`, text: t, url: "sheet#" + i, fetched_at: new Date().toISOString() })), "スプレッドシート"); } }
  catch (e) { $("#watch-out").textContent = "取得失敗: " + e.message; return; }
  const fresh = oItems.map((it, i) => i).filter(i => !oItems[i].error && !watchSeen.has(oItems[i].url)); oItems.forEach(i => { if (!i.error) watchSeen.add(i.url); }); const chk = fresh.filter(i => oJudged && needsCheck(oItems[i], oJudged[i]));
  $("#watch-out").textContent = `${new Date().toLocaleTimeString()} 取得 ${oItems.filter(i => !i.error).length} 件、新着 ${fresh.length}、うち要確認 ${chk.length}`; if (chk.length) { const body = chk.slice(0, 3).map(i => (oItems[i].title || "") + ": " + (oItems[i].text || "").slice(0, 60)).join("\n"); if (Notification?.permission === "granted") new Notification(`JEV: 要確認 ${chk.length} 件`, { body }); toast(`👁 監視: 要確認 ${chk.length} 件`); } }
$("#watch-toggle").onclick = async () => { if (watchTimer) { clearInterval(watchTimer); watchTimer = null; $("#watch-toggle").textContent = "監視を開始"; $("#watch-out").textContent = "停止しました"; return; } if (!jev) return status("モデルを読み込んでから開始してください"); try { await Notification?.requestPermission?.(); } catch { } const min = Math.max(1, +$("#watch-min").value || 10); watchSeen = new Set(oItems.filter(i => !i.error).map(i => i.url)); $("#watch-toggle").textContent = "監視を停止"; $("#watch-out").textContent = `${min} 分ごとに取り込みます（無料枠は quota.js が管理）`; watchTimer = setInterval(watchTick, min * 60e3); watchTick(); };

/* ツール箱: 検索式コンポーザー・ライブラリ・OSINT Framework */
const fillUrl = (u, value, d) => u.replace(/\{q\}/g, encodeURIComponent(value)).replace(/\{d\}/g, encodeURIComponent(d)).replace(/\{lat\}|\{lon\}/g, "").replace(/\{b64\}/g, btoa(unescape(encodeURIComponent(value))));
const gPicks = new Set();
export function renderComposer() { const q = $("#g-q").value.trim() || "キーワード"; const d = domainOf(q); const expr = compose(q, [...gPicks], d); $("#g-composer").innerHTML = `<div class="plan"><b>条件をボタンで足す</b><span class="muted small">（キーワード以外は入力不要。複数選択可）</span>${Object.entries(COMPOSER).map(([g, items]) => `<div class="chips"><span class="small muted" style="min-width:70px">${esc(g)}</span>${items.map(([n, t]) => `<span class="chip ${gPicks.has(t) ? "on" : ""}" data-t="${esc(t)}" title="${esc(t)}">${esc(n)}</span>`).join("")}</div>`).join("")}<div class="dork" style="border:0"><code id="g-expr">${esc(expr)}</code><span class="b"><button id="g-copy">コピー</button><a href="https://www.google.com/search?q=${encodeURIComponent(expr)}" target="_blank" rel="noopener"><button>Google</button></a><a href="https://www.bing.com/search?q=${encodeURIComponent(expr.replace(/\bintext:/g, "inbody:"))}" target="_blank" rel="noopener"><button>Bing</button></a><a href="https://duckduckgo.com/?q=${encodeURIComponent(expr)}" target="_blank" rel="noopener"><button>DDG</button></a><a href="https://yandex.com/search/?text=${encodeURIComponent(expr.replace(/\bfiletype:/g, "mime:"))}" target="_blank" rel="noopener"><button>Yandex</button></a><button id="g-clear" class="small">条件を消す</button></span></div><p class="hint">lang: / loc: は Bing・Yandex 用（Google では無視される）。after:/before: は Google 用。</p></div>`;
  $$("#g-composer .chip[data-t]").forEach(c => c.onclick = () => { const t = c.dataset.t; gPicks.has(t) ? gPicks.delete(t) : gPicks.add(t); renderComposer(); }); $("#g-copy").onclick = async () => { await navigator.clipboard.writeText(expr); toast("コピーしました"); }; $("#g-clear").onclick = () => { gPicks.clear(); renderComposer(); }; }
$("#g-q").addEventListener("input", renderComposer); renderComposer();
$("#g-run").onclick = () => { const q = $("#g-q").value.trim(); if (!q) return; const list = dorkList(q, domainOf(q)); $("#g-out").innerHTML = `<p class="hint">${list.length} 式 <button class="small d-all">すべてコピー</button></p>` + dorkHtml(list); wireDork($("#g-out"), list); }; $("#g-q").addEventListener("keydown", e => { if (e.key === "Enter") $("#g-run").click(); });
$("#fw-run").onclick = () => { const v = $("#fw-q").value.trim(); if (!v) return; const t = detectTarget(v); const types = t.type === "keyword" ? ["keyword"] : t.type === "url" ? ["url", "domain"] : [t.type]; $("#fw-out").innerHTML = `<p class="small muted">種類: ${esc(TARGET_TYPES[t.type] || t.type)}（自動調査は「調べる」で実行）</p>` + FRAMEWORK.map(c => `<details ${c.tools && c.types.some(x => types.includes(x)) ? "open" : ""}><summary>${esc(c.cat)}${c.no ? " — 実装しない" : ""}</summary><p class="small muted">${esc(c.no || c.note || "")}</p>${(c.tools || []).map(x => x.kind === "link" && x.url ? `<a href="${esc(fillUrl(x.url, t.value, domainOf(t.value)))}" target="_blank" rel="noopener"><button class="small">${esc(x.name)}</button></a> ` : `<span class="pill">${x.kind === "auto" ? "自動" : "端末内"}: ${esc(x.name)}</span> `).join("")}</details>`).join(""); }; $("#fw-q").addEventListener("keydown", e => { if (e.key === "Enter") $("#fw-run").click(); });
